use std::env;
use std::fs;
use std::path::Path;
use std::process;

mod cli;
mod config;
mod markdown;
mod html;
mod epub;

use cli::Args;

fn main() {
    let args = env::args().collect::<Vec<String>>();

    match cli::parse_args(&args) {
        Ok(args) => {
            if let Err(e) = run(args) {
                eprintln!("error: {}", e);
                process::exit(1);
            }
        }
        Err(e) => {
            eprintln!("error: {}", e);
            process::exit(2);
        }
    }
}

fn run(args: Args) -> Result<(), String> {
    println!("CROWBOOK 0.17.0");

    if args.version {
        return Ok(());
    }

    if args.help {
        println!("{}", cli::get_help_text());
        return Ok(());
    }

    if args.list_options {
        println!("{}", cli::get_options_list());
        return Ok(());
    }

    if let Some(template) = &args.print_template {
        println!("{}", cli::get_template(template)?);
        return Ok(());
    }

    if args.book_file.is_none() && args.create.is_empty() {
        return Err("You must pass the name of a book configuration file.\nFor more information try --help.".to_string());
    }

    Ok(())
}
EOF

