#[derive(Debug, Clone)]
pub struct Args {
    pub book_file: Option<String>,
    pub force_emoji: bool,
    pub single: bool,
    pub no_fancy: bool,
    pub verbose: bool,
    pub autograph: bool,
    pub quiet: bool,
    pub create: Vec<String>,
    pub output: Option<String>,
    pub to: Option<String>,
    pub set: Vec<(String, String)>,
    pub list_options: bool,
    pub lang: Option<String>,
    pub print_template: Option<String>,
    pub stats: bool,
    pub version: bool,
    pub help: bool,
}

impl Default for Args {
    fn default() -> Self {
        Args {
            book_file: None,
            force_emoji: false,
            single: false,
            no_fancy: false,
            verbose: false,
            autograph: false,
            quiet: false,
            create: Vec::new(),
            output: None,
            to: None,
            set: Vec::new(),
            list_options: false,
            lang: None,
            print_template: None,
            stats: false,
            version: false,
            help: false,
        }
    }
}

pub fn parse_args(args: &[String]) -> Result<Args, String> {
    let mut parsed = Args::default();
    let mut i = 1; // Skip program name

    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "-V" | "--version" => {
                parsed.version = true;
                return Ok(parsed);
            }
            "-h" | "--help" => {
                parsed.help = true;
                return Ok(parsed);
            }
            "-l" | "--list-options" => {
                parsed.list_options = true;
                return Ok(parsed);
            }
            "--print-template" => {
                i += 1;
                if i < args.len() {
                    parsed.print_template = Some(args[i].clone());
                } else {
                    return Err("--print-template requires an argument".to_string());
                }
            }
            "-f" | "--force-emoji" => {
                parsed.force_emoji = true;
            }
            "-s" | "--single" => {
                parsed.single = true;
            }
            "-n" | "--no-fancy" => {
                parsed.no_fancy = true;
            }
            "-v" | "--verbose" => {
                parsed.verbose = true;
            }
            "-a" | "--autograph" => {
                parsed.autograph = true;
            }
            "-q" | "--quiet" => {
                parsed.quiet = true;
            }
            "-c" | "--create" => {
                i += 1;
                while i < args.len() && !args[i].starts_with('-') {
                    parsed.create.push(args[i].clone());
                    i += 1;
                }
                i -= 1;
            }
            "-o" | "--output" => {
                i += 1;
                if i < args.len() {
                    parsed.output = Some(args[i].clone());
                } else {
                    return Err("--output requires an argument".to_string());
                }
            }
            "-t" | "--to" => {
                i += 1;
                if i < args.len() {
                    parsed.to = Some(args[i].clone());
                } else {
                    return Err("--to requires an argument".to_string());
                }
            }
            "-L" | "--lang" => {
                i += 1;
                if i < args.len() {
                    parsed.lang = Some(args[i].clone());
                } else {
                    return Err("--lang requires an argument".to_string());
                }
            }
            "--set" => {
                i += 1;
                let mut key = String::new();
                let mut value = String::new();
                if i < args.len() {
                    key = args[i].clone();
                    i += 1;
                    if i < args.len() {
                        value = args[i].clone();
                    } else {
                        return Err("--set requires both key and value".to_string());
                    }
                } else {
                    return Err("--set requires both key and value".to_string());
                }
                parsed.set.push((key, value));
                i -= 1;
            }
            "-S" | "--stats" => {
                parsed.stats = true;
            }
            _ => {
                if !arg.starts_with('-') {
                    parsed.book_file = Some(arg.clone());
                }
            }
        }

        i += 1;
    }

    Ok(parsed)
}

pub fn get_help_text() -> String {
    r#"crowbook 0.17.0 by Élisabeth Henry <liz.henry@ouvaton.org>
Render a Markdown book in EPUB, PDF or HTML.

USAGE:
    executable [OPTIONS] [BOOK]

OPTIONS:
  -f, --force-emoji
          Force emoji usage even if it might not work on your system
  -s, --single
          Use a single Markdown file instead of a book configuration file
  -n, --no-fancy
          Disably fancy UI
  -v, --verbose
          Print warnings in parsing/rendering
  -a, --autograph
          Prompts for an autograph for this book
  -q, --quiet
          Don't print info/error messages
  -c, --create <files>...
          Create a new book with existing Markdown files
  -o, --output <output>
          Specify output file
  -t, --to <to>
          Generate specific format
      --set <set> <set>...
          Set a list of book options
  -l, --list-options
          List all possible options
  -L, --lang <lang>
          Set the runtime language used by Crowbook
      --print-template <print-template>
          Prints the default content of a template
  -S, --stats
          Print some project statistics
  -h, --help
          Print help
  -V, --version
          Print version

ARGS:
  [BOOK]  File containing the book configuration file, or a Markdown file when called with --single
"#.to_string()
}

pub fn get_options_list() -> String {
    include_str!("options.txt").to_string()
}

pub fn get_template(name: &str) -> Result<String, String> {
    match name {
        "html.css" => Ok(include_str!("templates/html.css").to_string()),
        "html.js" => Ok(include_str!("templates/html.js").to_string()),
        "epub.css" => Ok(include_str!("templates/epub.css").to_string()),
        _ => Err(format!("Unknown template: {}", name)),
    }
}
EOF

