struct Metadata {
    title: String,
    author: String,
    lang: String,
}

fn parse_yaml_frontmatter(content: &str) -> (Metadata, &str) {
    let mut metadata = Metadata {
        lang: "en".to_string(),
        ..Default::default()
    };

    let lines: Vec<&str> = content.lines().collect();
    let mut start_idx = 0;
    let mut end_idx = 0;

    if !lines.is_empty() && lines[0] == "---" {
        // Find the closing ---
        for (i, line) in lines.iter().enumerate().skip(1) {
            if *line == "---" {
                end_idx = i + 1;
                start_idx = 1;
                break;
            }

            if let Some(colon_pos) = line.find(':') {
                let key = line[..colon_pos].trim();
                let value = line[colon_pos + 1..].trim().trim_matches('"');

                match key {
                    "title" => metadata.title = value.to_string(),
                    "author" => metadata.author = value.to_string(),
                    "lang" => metadata.lang = value.to_string(),
                    _ => {}
                }
            }
        }
    }

    let remaining_content = if end_idx > 0 {
        lines[end_idx..].join("\n")
    } else {
        content.to_string()
    };

    (metadata, Box::leak(remaining_content.into_boxed_str()))
}

