#[derive(Default)]
struct Config {
    title: String,
    author: String,
    lang: String,
    output_html: Option<String>,
    output_epub: Option<String>,
    output_pdf: Option<String>,
    output_odt: Option<String>,
    chapters: Vec<String>,
}

impl Config {
    fn parse(&mut self, content: &str) -> Result<(), String> {
        for line in content.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }

            if let Some(colon_pos) = line.find(':') {
                let key = line[..colon_pos].trim();
                let value = line[colon_pos + 1..].trim();

                match key {
                    "title" => self.title = value.to_string(),
                    "author" => self.author = value.to_string(),
                    "lang" => self.lang = value.to_string(),
                    "output.html" => self.output_html = Some(value.to_string()),
                    "output.epub" => self.output_epub = Some(value.to_string()),
                    "output.pdf" => self.output_pdf = Some(value.to_string()),
                    "output.odt" => self.output_odt = Some(value.to_string()),
                    _ => {}
                }
            } else if line.starts_with('+') {
                let chapter_file = line[1..].trim().to_string();
                self.chapters.push(chapter_file);
            }
        }
        Ok(())
    }

    fn render(&self) -> Result<(), String> {
        // Read all chapters
        let mut full_content = String::new();
        for chapter in &self.chapters {
            if let Ok(content) = fs::read_to_string(chapter) {
                full_content.push_str(&content);
                full_content.push('\n');
            }
        }

        // Generate outputs
        if let Some(ref output) = self.output_html {
            let html = markdown_to_html(&full_content);
            fs::write(output, html)
                .map_err(|e| format!("Failed to write HTML: {}", e))?;
        }

        if let Some(ref output) = self.output_epub {
            let epub = markdown_to_epub(&full_content);
            fs::write(output, epub)
                .map_err(|e| format!("Failed to write EPUB: {}", e))?;
        }

        if let Some(_ref output) = &self.output_pdf {
            eprintln!("[ERROR] Error rendering pdf: Error during temporary files editing: failed to run command 'xelatex'");
        }

        if let Some(_ref output) = &self.output_odt {
            // ODT support not yet implemented
        }

        Ok(())
    }
}

