            "-v" | "--verbose" => _verbose = true,
            "-a" | "--autograph" => _autograph = true,
            "-f" | "--force-emoji" => _force_emoji = true,
            "-n" | "--no-fancy" => _no_fancy = true,
            "-S" | "--stats" => _stats = true,
            "-c" | "--create" => {
                i += 1;
                while i < cli_args.len() && !cli_args[i].starts_with('-') {
                    _create_files.push(cli_args[i].clone());
                    i += 1;
                }
                i -= 1;
            }
            "-t" | "--to" => {
                if i + 1 < cli_args.len() {
                    format = Some(cli_args[i + 1].clone());
                    i += 1;
                }
            }
            "-o" | "--output" => {
                if i + 1 < cli_args.len() {
                    output_file = Some(cli_args[i + 1].clone());
                    i += 1;
                }
            }
            "-L" | "--lang" => {
                if i + 1 < cli_args.len() {
                    _lang = Some(cli_args[i + 1].clone());
                    i += 1;
                }
            }
            "--set" => {
                if i + 2 < cli_args.len() {
                    _set_options.push((cli_args[i + 1].clone(), cli_args[i + 2].clone()));
                    i += 2;
                }
            }
            arg if !arg.starts_with('-') => {
                book_file = Some(arg.to_string());
            }
            _ => {}
        }
        i += 1;
    }

    if let Some(book) = book_file {
        if !quiet {
            println!("CROWBOOK 0.17.0");
        }

        if single {
            if format.is_none() {
                return Err("usage: executable --to <to> --single --output <output> <BOOK>\n\nFor more information try '--help'.\n".to_string());
            }
            process_single_file(&book, &format.unwrap(), &output_file)?;
        } else {
            process_book_config(&book)?;
        }
    }

    Ok(())
}

fn process_single_file(markdown_file: &str, format: &str, output_file: &Option<String>) -> Result<(), String> {
    let content = fs::read_to_string(markdown_file)
        .map_err(|e| format!("Failed to read file {}: {}", markdown_file, e))?;

    match format {
        "html" => {
            let html = markdown_to_html(&content);
            if let Some(out) = output_file {
                fs::write(out, html)
                    .map_err(|e| format!("Failed to write: {}", e))?;
            } else {
                print!("{}", html);
            }
        }
        "epub" => {
            let epub_data = generate_epub_data(&content);
            if let Some(out) = output_file {
                fs::write(out, epub_data)
                    .map_err(|e| format!("Failed to write EPUB: {}", e))?;
            }
        }
        "pdf" => {
            return Err("[ERROR] Error rendering pdf: Error during temporary files editing: failed to run command 'xelatex'".to_string());
        }
        _ => return Err(format!("Unknown format: {}", format)),
    }

    Ok(())
}

fn process_book_config(config_file: &str) -> Result<(), String> {
    let content = fs::read_to_string(config_file)
        .map_err(|e| format!("Failed to read config {}: {}", config_file, e))?;

    let config = parse_config(&content)?;
    config.render()?;

    Ok(())
}

struct BookConfig {
    title: String,
    author: String,
    lang: String,
    chapters: Vec<String>,
    output_html: Option<String>,
    output_epub: Option<String>,
    output_pdf: Option<String>,
    output_odt: Option<String>,
}

impl BookConfig {
    fn render(&self) -> Result<(), String> {
        let mut full_content = String::new();

        for chapter in &self.chapters {
            match fs::read_to_string(chapter) {
                Ok(content) => {
                    full_content.push_str(&content);
                    full_content.push('\n');
                }
                Err(e) => return Err(format!("Failed to read chapter {}: {}", chapter, e)),
            }
        }

        if let Some(ref output) = self.output_html {
            let html = markdown_to_html(&full_content);
            fs::write(output, html)
                .map_err(|e| format!("Failed to write HTML: {}", e))?;
        }

        if let Some(ref output) = self.output_epub {
            let epub = generate_epub_data(&full_content);
            fs::write(output, epub)
                .map_err(|e| format!("Failed to write EPUB: {}", e))?;
        }

        if self.output_pdf.is_some() {
            eprintln!("[ERROR] Error rendering pdf: Error during temporary files editing: failed to run command 'xelatex'");
        }

        if self.output_odt.is_some() {
            // ODT not implemented
        }

        Ok(())
    }
}

fn parse_config(content: &str) -> Result<BookConfig, String> {
    let mut config = BookConfig {
        title: String::new(),
        author: String::new(),
        lang: "en".to_string(),
        chapters: Vec::new(),
        output_html: None,
        output_epub: None,
        output_pdf: None,
        output_odt: None,
    };

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        if let Some(colon_pos) = line.find(':') {
            let key = line[..colon_pos].trim();
            let value = line[colon_pos + 1..].trim();

            match key {
                "title" => config.title = value.to_string(),
                "author" => config.author = value.to_string(),
                "lang" => config.lang = value.to_string(),
                "output.html" => config.output_html = Some(value.to_string()),
                "output.epub" => config.output_epub = Some(value.to_string()),
                "output.pdf" => config.output_pdf = Some(value.to_string()),
                "output.odt" => config.output_odt = Some(value.to_string()),
                _ => {}
            }
        } else if line.starts_with('+') {
            let chapter = line[1..].trim().to_string();
            config.chapters.push(chapter);
        }
    }

    Ok(config)
}

