struct Frontmatter {
    title: String,
    author: String,
    lang: String,
}

fn parse_frontmatter(content: &str) -> (Frontmatter, &str) {
    let mut meta = Frontmatter {
        title: String::new(),
        author: String::new(),
        lang: "en".to_string(),
    };

    let lines: Vec<&str> = content.lines().collect();
    let mut body_start = 0;

    if !lines.is_empty() && lines[0] == "---" {
        for (i, line) in lines.iter().enumerate().skip(1) {
            if *line == "---" {
                body_start = i + 1;
                break;
            }

            if let Some(colon) = line.find(':') {
                let key = line[..colon].trim();
                let val = line[colon + 1..].trim().trim_matches('"');

                match key {
                    "title" => meta.title = val.to_string(),
                    "author" => meta.author = val.to_string(),
                    "lang" => meta.lang = val.to_string(),
                    _ => {}
                }
            }
        }
    }

    let remaining = if body_start > 0 {
        lines[body_start..].join("\n")
    } else {
        content.to_string()
    };

    (meta, Box::leak(remaining.into_boxed_str()))
}

fn parse_markdown(content: &str) -> String {
    let mut result = String::new();
    let lines: Vec<&str> = content.lines().collect();

    let mut chapter_count = 0;
    let mut para_count = 0;
    let mut in_chapter = false;
    let mut i = 0;

    while i < lines.len() {
        let line = lines[i].trim();

        if line.is_empty() {
            i += 1;
            continue;
        }

        if line.starts_with("# ") {
            if in_chapter {
                result.push_str("\n</div>\n\n");
            }

            let title = &line[2..];
            chapter_count += 1;
            para_count += 1;

            result.push_str(&format!("        <div id = \"chapter-{}\" class = \"chapter\">\n", chapter_count - 1));
            result.push_str(&format!("  <h1 id = 'link-{}'><span class = 'chapter-header'>Chapter {}</span><br />{}</h1>", para_count, chapter_count, title));
            in_chapter = true;
        } else if line.starts_with("## ") {
            let heading = &line[3..];
            para_count += 1;
            result.push_str(&format!("<h2 id = \"link-{}\">{{}} 1.{}</h2>\n", para_count, chapter_count));
        } else if line.starts_with("- ") {
            result.push_str("<li>");
            result.push_str(&line[2..]);
            result.push_str("</li>\n");
        } else if line.starts_with("> ") {
            result.push_str("<blockquote>");
            result.push_str(&line[2..]);
            result.push_str("</blockquote>\n");
        } else if line.starts_with("```") {
            result.push_str("<pre><code>");
            i += 1;
            while i < lines.len() && !lines[i].trim().starts_with("```") {
                result.push_str(lines[i]);
                result.push('\n');
                i += 1;
            }
            result.push_str("</code></pre>\n");
        } else if !line.is_empty() {
            para_count += 1;
            let converted = convert_inline_markdown(line);
            result.push_str(&format!("<p id = \"para-{}\">{}</p>\n", para_count, converted));
        }

        i += 1;
    }

    if in_chapter {
        result.push_str("\n</div>\n");
    }

    result
}

fn convert_inline_markdown(text: &str) -> String {
    let mut result = String::new();
    let mut chars = text.chars().peekable();

    while let Some(ch) = chars.next() {
        if ch == '*' {
            if chars.peek() == Some(&'*') {
                chars.next();
                result.push_str("<strong>");
                let mut bold = String::new();
                while let Some(c) = chars.next() {
                    if c == '*' && chars.peek() == Some(&'*') {
                        chars.next();
                        break;
                    }
                    bold.push(c);
                }
                result.push_str(&bold);
                result.push_str("</strong>");
            } else {
                result.push_str("<em>");
                let mut italic = String::new();
                while let Some(c) = chars.next() {
                    if c == '*' {
                        break;
                    }
                    italic.push(c);
                }
                result.push_str(&italic);
                result.push_str("</em>");
            }
        } else if ch == '`' {
            result.push_str("<code>");
            while let Some(c) = chars.next() {
                if c == '`' {
                    break;
                }
                result.push(c);
            }
            result.push_str("</code>");
        } else {
            result.push(ch);
        }
    }

    result
}

